interface User { id: number; name: string }
interface Admin extends User { level: number }

type Id = number | string;          // union
type Pair = [number, number];       // tuple
type Mod = User & { level: number };

interface User { email?: string }   // merges

function first<T>(xs: T[]): T | undefined {
  return xs[0];
}

first([1, 2, 3]);      // number | undefined
first(['a', 'b']);     // string | undefined

function pick<T, K extends keyof T>(o: T, k: K): T[K] {
  return o[k];
}

type Shape =
  | { kind: 'circle'; r: number }
  | { kind: 'square'; side: number };

function area(s: Shape) {
  if (s.kind === 'circle') return s.r ** 2 * 3.14;
  return s.side ** 2;
}

type Draft = Partial<User>;      // all optional
type Card = Pick<User, 'name'>;  // keep some
type NoId = Omit<User, 'id'>;    // drop some
